<?php $title = __('Employee Salary Expense'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="reports/salary-expense"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><a class="btn btn-outline" href="<?= e(url('reports/salary-expense', ['from' => $from, 'to' => $to, 'export' => 'csv'])) ?>"><?= __('CSV') ?></a><button class="btn btn-outline no-print" type="button" onclick="window.print()"><?= __('🖨 Print') ?></button></form>
<div class="alert alert-info"><?= __('Paid salary (posted journals),') ?><?= date_display($from) ?> → <?= date_display($to) ?>: <strong><?= money($sum) ?></strong></div>
<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Code') ?></th><th><?= __('Employee') ?></th><th><?= __('Department') ?></th><th class="num"><?= __('Payslips') ?></th><th class="num"><?= __('Basic') ?></th><th class="num"><?= __('Overtime') ?></th><th class="num"><?= __('Advances Ded.') ?></th><th class="num"><?= __('Loans Ded.') ?></th><th class="num"><?= __('Net Paid') ?></th></tr></thead>
<tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= e($r['code']) ?></td><td><?= e($r['name']) ?></td><td><?= e($r['department'] ?? '—') ?></td><td class="num"><?= (int)$r['payslips'] ?></td><td class="num"><?= number_format($r['basic'], 2) ?></td><td class="num"><?= number_format($r['overtime'], 2) ?></td><td class="num"><?= number_format($r['advances'], 2) ?></td><td class="num"><?= number_format($r['loans'], 2) ?></td><td class="num"><strong><?= money($r['net_paid']) ?></strong></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="9" class="muted"><?= __('No paid salary in range.') ?></td></tr><?php endif; ?></tbody>
<tfoot><tr><th colspan="8"><?= __('TOTAL NET PAID') ?></th><th class="num"><?= money($sum) ?></th></tr></tfoot></table></div></div>
